"""Tests for pkg.greet."""

from pkg import greet
from pkg.core import greet as greet_from_core


def test_greet_returns_hello():
    assert greet("World") == "Hello, World!"


def test_greet_uses_given_name():
    assert greet("Alice") == "Hello, Alice!"


def test_greet_is_exported_from_package():
    assert greet is greet_from_core
